function CentrifugalCasterMaker.init() CentrifugalCasterMaker.ironStock=18; CentrifugalCasterMaker.bronzeStock=14; CentrifugalCasterMaker.woodStock=8; CentrifugalCasterMaker.leatherStock=8; CentrifugalCasterMaker.silverStock=8; CentrifugalCasterMaker.goldStock=6; CentrifugalCasterMaker.jewelStock=4; CentrifugalCasterMaker.pearlStock=4; CentrifugalCasterMaker.productStock={}; CentrifugalCasterMaker.buildings={}; CentrifugalCasterMaker.maker=nil; CentrifugalCasterMaker.activeMaking={}; CentrifugalCasterMaker.totalProducts=0; CentrifugalCasterMaker.dayTimer=0; print("[CentrifugalCasterMaker] Royal Centrifugal Caster Maker System initialized (6 products, 4 buildings)") end
function CentrifugalCasterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CentrifugalCasterMaker.maker={name=n or ("Vrtinec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrtinec najet: %s (spretnost: %d)",CentrifugalCasterMaker.maker.name,s),"success") end; return true end
function CentrifugalCasterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CentrifugalCasterMaker.build(id) local ok,e=CentrifugalCasterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CentrifugalCasterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CentrifugalCasterMaker.getQualityBonus() local b=0; for _,bd in ipairs(CentrifugalCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CentrifugalCasterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CentrifugalCasterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CentrifugalCasterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CentrifugalCasterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CentrifugalCasterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CentrifugalCasterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CentrifugalCasterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CentrifugalCasterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CentrifugalCasterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CentrifugalCasterMaker.buildings==0 then return false,"Potrebna vrtilna delavnica" end; if not CentrifugalCasterMaker.maker then return false,"Potreben vrtinec" end; return true end
function CentrifugalCasterMaker.make(pt,qty) qty=qty or 1; local ok,e=CentrifugalCasterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CentrifugalCasterMaker.ironStock=CentrifugalCasterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CentrifugalCasterMaker.bronzeStock=CentrifugalCasterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CentrifugalCasterMaker.woodStock=CentrifugalCasterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CentrifugalCasterMaker.leatherStock=CentrifugalCasterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CentrifugalCasterMaker.silverStock=CentrifugalCasterMaker.silverStock-d.silverCost*qty end; if d.goldCost then CentrifugalCasterMaker.goldStock=CentrifugalCasterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CentrifugalCasterMaker.jewelStock=CentrifugalCasterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CentrifugalCasterMaker.pearlStock=CentrifugalCasterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CentrifugalCasterMaker.maker then t=math.max(1,t-math.floor(CentrifugalCasterMaker.maker.skill/13)) end; table.insert(CentrifugalCasterMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CentrifugalCasterMaker.completeMaking(m) local q=1.0+(CentrifugalCasterMaker.getQualityBonus()/100); if CentrifugalCasterMaker.maker then q=q+(CentrifugalCasterMaker.maker.skill/140) end; q=math.min(2.5,q); CentrifugalCasterMaker.productStock[m.productType]=(CentrifugalCasterMaker.productStock[m.productType] or 0)+m.quantity; CentrifugalCasterMaker.totalProducts=CentrifugalCasterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CentrifugalCasterMaker.maker then CentrifugalCasterMaker.maker.itemsMade=CentrifugalCasterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CentrifugalCasterMaker.maker.skill=math.min(100,CentrifugalCasterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrtilka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function CentrifugalCasterMaker.update(dt) if not _G.state then return end; CentrifugalCasterMaker.dayTimer=CentrifugalCasterMaker.dayTimer+dt; if CentrifugalCasterMaker.dayTimer>=30 then CentrifugalCasterMaker.dayTimer=0; for i=#CentrifugalCasterMaker.activeMaking,1,-1 do local m=CentrifugalCasterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CentrifugalCasterMaker.completeMaking(m); table.remove(CentrifugalCasterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CentrifugalCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CentrifugalCasterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CentrifugalCasterMaker.getStats() return {ironStock=CentrifugalCasterMaker.ironStock,bronzeStock=CentrifugalCasterMaker.bronzeStock,woodStock=CentrifugalCasterMaker.woodStock,leatherStock=CentrifugalCasterMaker.leatherStock,silverStock=CentrifugalCasterMaker.silverStock,goldStock=CentrifugalCasterMaker.goldStock,jewelStock=CentrifugalCasterMaker.jewelStock,pearlStock=CentrifugalCasterMaker.pearlStock,productStock=CentrifugalCasterMaker.productStock,numBuildings=#CentrifugalCasterMaker.buildings,hasMaker=CentrifugalCasterMaker.maker~=nil,makerName=CentrifugalCasterMaker.maker and CentrifugalCasterMaker.maker.name or "—",makerSkill=CentrifugalCasterMaker.maker and CentrifugalCasterMaker.maker.skill or 0,activeMaking=#CentrifugalCasterMaker.activeMaking,totalProducts=CentrifugalCasterMaker.totalProducts} end
